#include "core.h"

// MD KIT: generated by tools/make_engine.py. Each key holds its own machine,
// chosen with Shift and the first two encoders (the family, then the machine), and that machine's eight controls
// (kit.h), which the SDK saves with the project. The sound is in the voice
// modules: TRX-BD (voices/trx_bd.hpp), TRX-SD (voices/trx_sd.hpp), TRX-XT (voices/trx_tom.hpp), TRX-CP (voices/trx_cp.hpp), TRX-RS (voices/trx_rs.hpp), TRX-CB (voices/trx_cb.hpp), TRX-CH (voices/trx_hat.hpp), TRX-OH (voices/trx_hat.hpp), TRX-CY (voices/trx_cy.hpp), TRX-MA (voices/trx_ma.hpp), TRX-CL (voices/trx_cl.hpp), TRX-XC (voices/trx_tom.hpp), TRX-B2 (voices/trx_b2.hpp), EFM-BD (voices/efm_bd.hpp), EFM-SD (voices/efm_sd.hpp), EFM-XT (voices/efm_xt.hpp), EFM-CP (voices/efm_cp.hpp), EFM-RS (voices/efm_rs.hpp), EFM-CB (voices/efm_cb.hpp), EFM-HH (voices/efm_hh.hpp), EFM-CY (voices/efm_cy.hpp), PI-BD (voices/pi_bd.hpp), PI-SD (voices/pi_sd.hpp), PI-MT (voices/pi_mt.hpp), PI-ML (voices/pi_ml.hpp), PI-MA (voices/pi_ma.hpp), PI-RS (voices/pi_rs.hpp), PI-RC (voices/pi_cymbal.hpp), PI-CC (voices/pi_cymbal.hpp), PI-HH (voices/pi_cymbal.hpp), GND-SN (voices/gnd_sn.hpp), GND-NS (voices/gnd_ns.hpp), GND-IM (voices/gnd_im.hpp).
namespace mdkit {
void drum_defaults(u32 key, opxy::u8* model, opxy::u8* controls) {
    const u32 k = key >= 53 && key < 53 + kit::keys ? key - 53 : 0;
    *model = kit::key_model[k];
    for (u32 c = 0; c < 8; ++c) controls[c] = kit::key_values[k][c];
}
const char* model_name(u32 model) { return kit::model[model < kit::models ? model : 0].name; }
const char* parameter_name(u32 model, u32 slot) {
    return slot < 8 ? kit::model[model < kit::models ? model : 0].labels[slot] : "";
}
u32 parameter_count(u32 model) { return kit::model[model < kit::models ? model : 0].count; }

inline void begin_member(Voice& voice, Shared& shared) {
    switch (voice.machine) {
    case 0: md::trx_bd::reset(voice.u.m0, shared.common, voice.owner); break;
    case 1: md::trx_sd::reset(voice.u.m1, shared.common, voice.owner); break;
    case 2: md::trx_xt::reset(voice.u.m2, shared.common, voice.owner); break;
    case 3: md::trx_cp::reset(voice.u.m3, shared.common, voice.owner); break;
    case 4: md::trx_rs::reset(voice.u.m4, shared.common, voice.owner); break;
    case 5: md::trx_cb::reset(voice.u.m5, shared.common, voice.owner); break;
    case 6: md::trx_ch::reset(voice.u.m6, shared.common, voice.owner); break;
    case 7: md::trx_oh::reset(voice.u.m7, shared.common, voice.owner); break;
    case 8: md::trx_cy::reset(voice.u.m8, shared.common, voice.owner); break;
    case 9: md::trx_ma::reset(voice.u.m9, shared.common, voice.owner); break;
    case 10: md::trx_cl::reset(voice.u.m10, shared.common, voice.owner); break;
    case 11: md::trx_xc::reset(voice.u.m11, shared.common, voice.owner); break;
    case 12: md::trx_b2::reset(voice.u.m12, shared.common, voice.owner); break;
    case 13: md::efm_bd::reset(voice.u.m13, shared.common, voice.owner); break;
    case 14: md::efm_sd::reset(voice.u.m14, shared.common, voice.owner); break;
    case 15: md::efm_xt::reset(voice.u.m15, shared.common, voice.owner); break;
    case 16: md::efm_cp::reset(voice.u.m16, shared.common, voice.owner); break;
    case 17: md::efm_rs::reset(voice.u.m17, shared.common, voice.owner); break;
    case 18: md::efm_cb::reset(voice.u.m18, shared.common, voice.owner); break;
    case 19: md::efm_hh::reset(voice.u.m19, shared.common, voice.owner); break;
    case 20: md::efm_cy::reset(voice.u.m20, shared.common, voice.owner); break;
    case 21: md::pi_bd::reset(voice.u.m21, shared.common, voice.owner); break;
    case 22: md::pi_sd::reset(voice.u.m22, shared.common, voice.owner); break;
    case 23: md::pi_mt::reset(voice.u.m23, shared.common, voice.owner); break;
    case 24: md::pi_ml::reset(voice.u.m24, shared.common, voice.owner); break;
    case 25: md::pi_ma::reset(voice.u.m25, shared.common, voice.owner); break;
    case 26: md::pi_rs::reset(voice.u.m26, shared.common, voice.owner); break;
    case 27: md::pi_rc::reset(voice.u.m27, shared.common, voice.owner); break;
    case 28: md::pi_cc::reset(voice.u.m28, shared.common, voice.owner); break;
    case 29: md::pi_hh::reset(voice.u.m29, shared.common, voice.owner); break;
    case 30: md::gnd_sn::reset(voice.u.m30, shared.common, voice.owner); break;
    case 31: md::gnd_ns::reset(voice.u.m31, shared.common, voice.owner); break;
    case 32: md::gnd_im::reset(voice.u.m32, shared.common, voice.owner); break;
    default: return;
    }
    switch (voice.machine) {
    case 0: md::trx_bd::trigger(voice.u.m0, shared.common); break;
    case 1: md::trx_sd::trigger(voice.u.m1, shared.common); break;
    case 2: md::trx_xt::trigger(voice.u.m2, shared.common); break;
    case 3: md::trx_cp::trigger(voice.u.m3, shared.common); break;
    case 4: md::trx_rs::trigger(voice.u.m4, shared.common); break;
    case 5: md::trx_cb::trigger(voice.u.m5, shared.common); break;
    case 6: md::trx_ch::trigger(voice.u.m6, shared.common); break;
    case 7: md::trx_oh::trigger(voice.u.m7, shared.common); break;
    case 8: md::trx_cy::trigger(voice.u.m8, shared.common); break;
    case 9: md::trx_ma::trigger(voice.u.m9, shared.common); break;
    case 10: md::trx_cl::trigger(voice.u.m10, shared.common); break;
    case 11: md::trx_xc::trigger(voice.u.m11, shared.common); break;
    case 12: md::trx_b2::trigger(voice.u.m12, shared.common); break;
    case 13: md::efm_bd::trigger(voice.u.m13, shared.common); break;
    case 14: md::efm_sd::trigger(voice.u.m14, shared.common); break;
    case 15: md::efm_xt::trigger(voice.u.m15, shared.common); break;
    case 16: md::efm_cp::trigger(voice.u.m16, shared.common); break;
    case 17: md::efm_rs::trigger(voice.u.m17, shared.common); break;
    case 18: md::efm_cb::trigger(voice.u.m18, shared.common); break;
    case 19: md::efm_hh::trigger(voice.u.m19, shared.common); break;
    case 20: md::efm_cy::trigger(voice.u.m20, shared.common); break;
    case 21: md::pi_bd::trigger(voice.u.m21, shared.common); break;
    case 22: md::pi_sd::trigger(voice.u.m22, shared.common); break;
    case 23: md::pi_mt::trigger(voice.u.m23, shared.common); break;
    case 24: md::pi_ml::trigger(voice.u.m24, shared.common); break;
    case 25: md::pi_ma::trigger(voice.u.m25, shared.common); break;
    case 26: md::pi_rs::trigger(voice.u.m26, shared.common); break;
    case 27: md::pi_rc::trigger(voice.u.m27, shared.common); break;
    case 28: md::pi_cc::trigger(voice.u.m28, shared.common); break;
    case 29: md::pi_hh::trigger(voice.u.m29, shared.common); break;
    case 30: md::gnd_sn::trigger(voice.u.m30, shared.common); break;
    case 31: md::gnd_ns::trigger(voice.u.m31, shared.common); break;
    case 32: md::gnd_im::trigger(voice.u.m32, shared.common); break;
    default: break;
    }
}

inline void initialize(Voice& voice, Shared&, u32 owner) {
    voice.machine = 0;
    voice.next = 0;
    voice.owner = owner;
    voice.pending = 0;
    voice.quiet = voice.done = 0;
}
inline void start(Voice& voice, Shared&, u32) { voice.pending = 1; }

// A sound has ended once it has stayed 12 dB under the floor (-90 dB) for 90 ms
// with nothing still to come: a DUAL strike, a clap, a shake, a grab or a
// retrig. A long tail hovering at the floor would come back over it; 12 dB
// under, none does (tests/sound.cpp). Its voice then writes silence without
// running the machine, and finished tells the SDK it may free the voice.
const i32 quiet_floor = 1 << 16, quiet_under = quiet_floor >> 2;
const u32 quiet_blocks = 62;
inline bool waiting(const Voice& voice) {
    switch (voice.machine) {
    case 3: return md::trx_cp::waiting(voice.u.m3);
    case 9: return md::trx_ma::waiting(voice.u.m9);
    case 10: return md::trx_cl::waiting(voice.u.m10);
    case 16: return md::efm_cp::waiting(voice.u.m16);
    case 27: return md::pi_cymbal::waiting(voice.u.m27);
    case 28: return md::pi_cymbal::waiting(voice.u.m28);
    case 29: return md::pi_cymbal::waiting(voice.u.m29);
    case 30: return md::gnd_sn::waiting(voice.u.m30);
    default: return false;
    }
}
inline bool finished(const Voice& voice, const Shared&) { return voice.done != 0; }
inline void destroy(Voice&, Shared&, u32) {}
inline void drum_select(Voice& voice, Shared&, u32, u32 model) { voice.next = model < kit::models ? model : 0; }

// The machines are voiced at middle C and tuned by their own PTCH, as on the
// original, so the note's pitch is not used.
inline void render(Voice& voice, Shared& shared, u32, opxy::Output output, opxy::Parameters parameters, opxy::Pitch) {
    if (voice.pending) voice.quiet = voice.done = 0;
    if (voice.done) {
        for (unsigned i = 0; i < opxy::block_frames; ++i) output[i] = 0;
        return;
    }
    if (voice.pending || voice.next != voice.machine) {
        voice.pending = 0;
        voice.machine = voice.next;
        begin_member(voice, shared);
    }
    i32 own[8];
    kit::controls(voice.machine, parameters, own);
    u32 tuned[opxy::block_frames];
    for (unsigned i = 0; i < opxy::block_frames; ++i) tuned[i] = ::md::kit::middle_c;
    switch (voice.machine) {
    case 0: md::trx_bd::render(voice.u.m0, shared.common, output, own, tuned); break;
    case 1: md::trx_sd::render(voice.u.m1, shared.common, output, own, tuned); break;
    case 2: md::trx_xt::render(voice.u.m2, shared.common, output, own, tuned); break;
    case 3: md::trx_cp::render(voice.u.m3, shared.common, output, own, tuned); break;
    case 4: md::trx_rs::render(voice.u.m4, shared.common, output, own, tuned); break;
    case 5: md::trx_cb::render(voice.u.m5, shared.common, output, own, tuned); break;
    case 6: md::trx_ch::render(voice.u.m6, shared.common, output, own, tuned); break;
    case 7: md::trx_oh::render(voice.u.m7, shared.common, output, own, tuned); break;
    case 8: md::trx_cy::render(voice.u.m8, shared.common, output, own, tuned); break;
    case 9: md::trx_ma::render(voice.u.m9, shared.common, output, own, tuned); break;
    case 10: md::trx_cl::render(voice.u.m10, shared.common, output, own, tuned); break;
    case 11: md::trx_xc::render(voice.u.m11, shared.common, output, own, tuned); break;
    case 12: md::trx_b2::render(voice.u.m12, shared.common, output, own, tuned); break;
    case 13: md::efm_bd::render(voice.u.m13, shared.common, output, own, tuned); break;
    case 14: md::efm_sd::render(voice.u.m14, shared.common, output, own, tuned); break;
    case 15: md::efm_xt::render(voice.u.m15, shared.common, output, own, tuned); break;
    case 16: md::efm_cp::render(voice.u.m16, shared.common, output, own, tuned); break;
    case 17: md::efm_rs::render(voice.u.m17, shared.common, output, own, tuned); break;
    case 18: md::efm_cb::render(voice.u.m18, shared.common, output, own, tuned); break;
    case 19: md::efm_hh::render(voice.u.m19, shared.common, output, own, tuned); break;
    case 20: md::efm_cy::render(voice.u.m20, shared.common, output, own, tuned); break;
    case 21: md::pi_bd::render(voice.u.m21, shared.common, output, own, tuned); break;
    case 22: md::pi_sd::render(voice.u.m22, shared.common, output, own, tuned); break;
    case 23: md::pi_mt::render(voice.u.m23, shared.common, output, own, tuned); break;
    case 24: md::pi_ml::render(voice.u.m24, shared.common, output, own, tuned); break;
    case 25: md::pi_ma::render(voice.u.m25, shared.common, output, own, tuned); break;
    case 26: md::pi_rs::render(voice.u.m26, shared.common, output, own, tuned); break;
    case 27: md::pi_rc::render(voice.u.m27, shared.common, output, own, tuned); break;
    case 28: md::pi_cc::render(voice.u.m28, shared.common, output, own, tuned); break;
    case 29: md::pi_hh::render(voice.u.m29, shared.common, output, own, tuned); break;
    case 30: md::gnd_sn::render(voice.u.m30, shared.common, output, own, tuned); break;
    case 31: md::gnd_ns::render(voice.u.m31, shared.common, output, own, tuned); break;
    case 32: md::gnd_im::render(voice.u.m32, shared.common, output, own, tuned); break;
    default: for (unsigned i = 0; i < opxy::block_frames; ++i) output[i] = 0; break;
    }
    bool loud = false;
    for (unsigned i = 0; i < opxy::block_frames; ++i) loud = loud || output[i] >= quiet_under || output[i] <= -quiet_under;
    voice.quiet = loud ? 0 : voice.quiet + 1;
    if (voice.quiet >= quiet_blocks && !waiting(voice)) voice.done = 1;
}
}
